Vou incluir linhas comentadas detalhadas para explicar cada parte do código:

```cpp
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h> // Para open(), read() e write()
#include <fcntl.h>   // Para F_DNODIR

#define MOTOR_1_PIN 1     // PINO DO PRIMEIRO MOTO
#define MOTOR_2_PIN 2     // PINO DO SEGUNDO MOTO

int main(void) {
    const char *device = "/dev/gpio"; // Caminho para o arquivo gpio
    struct ioperm perm;              // Estrutura para definir permissão de acesso aos registradores GPIO
    unsigned short value = 0;         // Valor zero inicialmente (desligado)

    printf("Iniciando controle dos motores...\n");

    // Abre o dispositivo /dev/gpio
    int fd = open(device, O_RDWR);
    if (-one == fd) {
        perror("Erro abrindo /dev/gpio");
        return 1;
    }

    // Define a direção dos pinos como saída
    perm.addr = &MOTOR_1_PIN | 0x2000; // Endereço alto bits setados para indicar registro de direção
    perm.cntl = sizeof(value);          // Contagem de bytes afetados (1 byte nesta caso)
    perm.val  = 0;                      // Direita (0 - baixa tensão aplicada), esquerda (1)
    ioperm((char*)&perm, 1, 1);       // Aplica a configuração

    // Configura o segundo motor
    perm.addr += 2;                    // Avança duas posições no espaço de endereçamento
    ioperm((char*)&perm, 1, 0);        // Desativa o segundo motor temporariamente

    // Liga ambos os motores simultaneamente
    value = 0xFF;                     // Ambos ligados (10010011 binário)
    write(fd, &value, sizeof(value));  // Escreve valor no registrador correspondente

    sleep(1);                         // Espera 1 segundo

    // Reverte sentido rotação do primeiro motor
    value &= ~(0x01 << 0);             // Inverte bit menos significativo (~00110011)
    write(fd, &value, sizeof(value));  // Atualiza estado do primeiro motor

    sleep(1);                         // Espera 1 segundo

    // Reinicia estados originais
    value |= (0x01 << 0);               // Restaura bit original 00110011
    write(fd, &value, sizeof(value));  // Salva mudanças

    close(fd);                         // Fecha conexão com o dispositivo
    return 0;
