    if (!writeSysfs("/sys/class/gpio/gpio17/value", "0")) return 1;
    if (!writeSysfs("/sys/class/gpio/gpio18/value", "0")) return 1;
    if (!writeSysfs("/sys/class/gpio/gpio22/value", "0")) return 1;
    if (!writeSysfs("/sys/class/gpio/gpio23/value", "0")) return 1;
