    gpiod_line_set_value(in3, 1); // Motor 2 direction input A HIGH.
    gpiod_line_set_value(in4, 0); // Motor 2 direction input B LOW.
    sleep(2);                     // Keep this direction for two seconds.

    // Set all inputs LOW briefly before changing direction.
    gpiod_line_set_value(in1, 0);
    gpiod_line_set_value(in2, 0);
    gpiod_line_set_value(in3, 0);
    gpiod_line_set_value(in4, 0);
    sleep(1);                     // Pause for one second.

