    gpiod_line_set_value(in1, 0);
    gpiod_line_set_value(in2, 1);
    gpiod_line_set_value(in3, 0);
    gpiod_line_set_value(in4, 1);
    sleep(2);                     // Run in the opposite direction for two seconds.

